1://! Build script for op-plugins.
2://!
3://! Generates `SCHEMA_CONTENT_HASH` — a sha256 digest of the
4://! `ContainerIdentitySled` struct definition text. The hash is written to
5://! `OUT_DIR/identity_sled_schema_hash.txt` and imported via `include_str!`
6://! in `identity_sled.rs`.
7://!
8://! The hash changes whenever a field is added, removed, reordered, or retyped
9://! in `ContainerIdentitySled`, providing automatic drift detection for
10://! consumers that compare stored records against the compiled shape.
11:
12:use sha2::{Digest, Sha256};
13:
14:fn main() {
15:    // Re-run if the struct definition changes.
16:    println!("cargo:rerun-if-changed=src/state_plugins/identity_sled.rs");
17:
18:    let src = std::fs::read_to_string("src/state_plugins/identity_sled.rs")
19:        .expect("failed to read src/state_plugins/identity_sled.rs");
20:
21:    let struct_text = extract_struct_body(&src, "ContainerIdentitySled")
22:        .expect("ContainerIdentitySled struct definition not found in source");
23:
24:    let hash = hex_encode(&Sha256::digest(struct_text.as_bytes()));
25:
26:    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR not set");
27:    let out_path = std::path::Path::new(&out_dir).join("identity_sled_schema_hash.txt");
28:    std::fs::write(&out_path, &hash).expect("failed to write identity_sled_schema_hash.txt");
29:
30:    println!("cargo:rustc-env=SCHEMA_CONTENT_HASH={hash}");
31:}
32:
33:/// Extract the text from `pub struct <name> {` to the matching closing `}`,
34:/// inclusive. This captures all field definitions, types, and inline
35:/// attributes — the canonical shape of the record.
36:fn extract_struct_body(src: &str, struct_name: &str) -> Option<String> {
37:    let needle = format!("pub struct {struct_name} {{");
38:    let start = src.find(&needle)?;
39:
40:    // Find the matching closing brace by counting depth.
41:    let brace_start = src[start..].find('{')? + start;
42:    let mut depth = 0i32;
43:    let mut end = brace_start;
44:    for (i, ch) in src[brace_start..].char_indices() {
45:        match ch {
46:            '{' => depth += 1,
47:            '}' => {
48:                depth -= 1;
49:                if depth == 0 {
50:                    end = brace_start + i + 1;
51:                    break;
52:                }
53:            }
54:            _ => {}
55:        }
56:    }
57:
58:    Some(src[start..end].to_string())
59:}
60:
61:fn hex_encode(bytes: &[u8]) -> String {
62:    let mut out = String::with_capacity(bytes.len() * 2);
63:    for &b in bytes {
64:        out.push_str(&format!("{b:02x}"));
65:    }
66:    out
67:}

