def ask_noul(state, question, options=None):
    body = {
        "state": state,
        "questions": [
            {
                "name": "is_executable_logic",
                "kind": "Noul",
                "statement": question,
                "criteria": {
                    "yes": "The text contains executable Rust logic: function definitions, branches, parsing, protocol handling, state machines, error handling, retries, or serialization.",
                    "no": "The text is purely a name, identifier, comment, doc string, string literal, error message text, environment variable name, constant, path string, feature flag, or module declaration."
                }
            }
        ]
    }
    conn = http.client.HTTPSConnection(host)
    conn.request("POST", "/v1/systemone", json.dumps(body), {
        "Authorization": f"Bearer {key}",
        "Content-Type": "application/json"
    })
    resp = conn.getresponse()
    data = json.loads(resp.read())
    conn.close()
    return data

